def go_reader(seed):
    state = {"ctr": 0, "buf": b""}

    def rng(buf, context):
        while len(state["buf"]) < len(buf):
            c = struct.pack("<Q", state["ctr"])
            state["ctr"] += 1
            state["buf"] += hashlib.sha256(seed.encode() + c).digest()
        buf[:] = state["buf"][:len(buf)]
        state["buf"] = state["buf"][len(buf):]

    return rng


class TestByteOrder(unittest.TestCase):
    def test_le32_to_host(self):
        data = bytes(range(1, 10))
        buf = bytearray(data)
        highctidh._le32_to_host(memoryview(buf))
        self.assertEqual(struct.unpack("=2I", buf[:8]), (0x04030201, 0x08070605))
        self.assertEqual(buf[8], 9)
        with mock.patch.object(sys, "byteorder", "big"):
            buf = bytearray(data)
            highctidh._le32_to_host(memoryview(buf))
            self.assertEqual(bytes(buf), bytes([4, 3, 2, 1, 8, 7, 6, 5, 9]))
        with mock.patch.object(sys, "byteorder", "little"):
            buf = bytearray(data)
            highctidh._le32_to_host(memoryview(buf))
            self.assertEqual(bytes(buf), data)

    def test_public_key_bytes_little_endian(self):
        for size in (511, 512, 1024, 2048):
            with self.subTest(size=size):
                c = ctidh(size)
                pk = c.public_key()
                for i in range(len(pk.A)):
                    pk.A[i] = 0x0102030405060708 + i
                b = bytes(pk)
                self.assertEqual(b[:8], bytes([8, 7, 6, 5, 4, 3, 2, 1]))
                pk2 = c.public_key.frombytes(b, validate=False)
                self.assertEqual(list(pk2.A), list(pk.A))

    def test_go_sampler_vectors(self):
        for size, seed, sk, pk in GO_SAMPLER_VECTORS:
            with self.subTest(size=size, seed=seed):
                c = ctidh(size)
                key = c.generate_secret_key(rng=go_reader(seed))
                self.assertEqual(bytes(key).hex(), sk)
                self.assertEqual(bytes(c.derive_public_key(key)).hex(), pk)


if __name__ == "__main__":
    unittest.main()
